{
  "items": [
    {
      "name": "csSup_le",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLattice α] {s : Set α} {a : α}, s.Nonempty → (∀ b ∈ s, b ≤ a) → sSup s ≤ a"
    },
    {
      "name": "csSup_le_iff",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLattice α] {s : Set α} {a : α},\n  BddAbove s → s.Nonempty → (sSup s ≤ a ↔ ∀ b ∈ s, b ≤ a)"
    },
    {
      "name": "ciSup_le_iff",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Indexed",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ι : Sort u_4} [inst : ConditionallyCompleteLattice α] [Nonempty ι] {f : ι → α} {a : α},\n  BddAbove (Set.range f) → (iSup f ≤ a ↔ ∀ (i : ι), f i ≤ a)"
    },
    {
      "name": "ConditionallyCompleteLattice.csSup_le",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_5} [self : ConditionallyCompleteLattice α] (s : Set α) (a : α),\n  s.Nonempty → a ∈ upperBounds s → sSup s ≤ a"
    },
    {
      "name": "le_csSup",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLattice α] {s : Set α} {a : α}, BddAbove s → a ∈ s → a ≤ sSup s"
    },
    {
      "name": "ciSup_le",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Indexed",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ι : Sort u_4} [inst : ConditionallyCompleteLattice α] [Nonempty ι] {f : ι → α} {c : α},\n  (∀ (x : ι), f x ≤ c) → iSup f ≤ c"
    }
  ]
}
